<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {ui} from '../state/device';import {t} from '../state/appearance';import {useLiveCommand} from '../state/liveCommand';import Icon from '../components/Icon.vue';import InfoButton from '../components/InfoButton.vue';
const props=defineProps<{send:(path:string,data:Record<string,unknown>)=>Promise<void>}>();
const strip=computed(()=>ui.summary?.strip),enabled=ref(true),driver=ref('rmt'),mode=ref('solid'),color=ref('#ffa030'),brightness=ref(20),period=ref(1000),ready=ref(false);
let hydrating=false;
watch(()=>ui.boot,()=>{ready.value=false;},{flush:'sync'});
const modes=computed(()=>[{id:'solid',label:t('Один цвет','Solid'),icon:'sun'},{id:'chase',label:t('Бегущий огонь','Chase'),icon:'player-track-next'},{id:'rainbow',label:t('Радуга','Rainbow'),icon:'palette'}]);
const invalid=computed(()=>!Number.isInteger(period.value)||period.value<20||period.value>5000?t('Период: 20–5000 мс','Period: 20–5000 ms'):'');
function payload():Record<string,unknown>|null{return invalid.value||!/^#[0-9a-f]{6}$/i.test(color.value)?null:{enabled:enabled.value,driver:driver.value,mode:mode.value,color:parseInt(color.value.slice(1),16),brightness_pct:Number(brightness.value),period_ms:Number(period.value)};}
const live=useLiveCommand<Record<string,unknown>>(data=>props.send('/api/v2/strip',data));
watch([strip,live.sending,live.pending],([s,sending,pending])=>{
    if(!s||sending||pending||(ready.value&&invalid.value))return;
    // Reconcile other clients and reboot state without echoing telemetry back as
    // commands. Never overwrite a local edit while its command is still queued.
    hydrating=true;enabled.value=s.enabled;driver.value=s.requested_driver;mode.value=s.mode;
    color.value='#'+s.color.toString(16).padStart(6,'0');brightness.value=s.brightness_pct;period.value=s.period_ms;ready.value=true;hydrating=false;
},{immediate:true});
watch([enabled,mode,color,brightness,period],(next,previous)=>{if(ready.value&&!hydrating)live.update(payload(),next[0]!==previous[0]||next[1]!==previous[1]);},{flush:'sync'});
const hex=(n:number)=>'#'+n.toString(16).padStart(6,'0');
</script>
<template><section class="panel" v-if="ui.info?.capabilities.strip?.supported"><div class="panel-head"><h2><Icon name="sun"/>WS2812 / GPIO{{strip?.gpio??'—'}} / {{strip?.count??0}} RGB</h2><InfoButton label="WS2812" :text="t('Изменения отправляются сразу. При движении ползунка — до 10 команд/с, одна команда в работе; последняя позиция обязательно отправляется. Пиксели ниже — состояние, полученное от устройства.','Changes are sent immediately. Sliders send up to 10 commands/s with one in flight; the final position is always sent. Pixels below show state received from the device.')"/></div><div class="rgb-strip" role="img" :aria-label="t('Состояние RGB-светодиодов','RGB LED state')"><span v-for="(pixel,i) in strip?.pixels??Array(10).fill(0)" :key="i" :style="{'--pixel':hex(pixel)}" :data-color="hex(pixel)"><i></i><small>{{i+1}}</small></span></div><div class="experiment-form"><div class="effect-field"><span class="label">{{t('Драйвер','Driver')}}</span><div class="effect-buttons" role="group" :aria-label="t('Драйвер RGB','RGB driver')" data-testid="strip-driver"><button v-for="id in strip?.available_drivers??['rmt','spi']" :key="id" type="button" :data-testid="'strip-driver-'+id" :aria-pressed="strip?.driver===id" :class="{active:strip?.driver===id}" :disabled="!ready||!ui.httpOnline" @click="driver=id;live.update(payload(),true)">{{id.toUpperCase()}}</button></div></div><div class="effect-field"><span class="label">{{t('Эффект','Effect')}}</span><div class="effect-buttons" role="group" :aria-label="t('Эффект RGB','RGB effect')" data-testid="strip-mode"><button v-for="effect in modes" :key="effect.id" type="button" :data-testid="'strip-mode-'+effect.id" :aria-pressed="mode===effect.id" :class="{active:mode===effect.id}" :disabled="!ready||!ui.httpOnline" @click="mode=effect.id"><Icon :name="effect.icon"/>{{effect.label}}</button></div></div><label>{{t('Цвет','Color')}}<input v-model="color" type="color" :disabled="!ready||!ui.httpOnline||mode==='rainbow'" data-testid="strip-color"></label><label>{{t('Период, мс','Period, ms')}}<input v-model.number="period" type="number" min="20" max="5000" step="10" :disabled="!ready||!ui.httpOnline||mode==='solid'" data-testid="strip-period"></label><div class="slider-row"><label for="strip-brightness">{{t('Яркость','Brightness')}} <b>{{brightness}}%</b></label><input id="strip-brightness" v-model.number="brightness" type="range" min="0" max="100" :disabled="!ready||!ui.httpOnline"></div><label class="checkbox"><input v-model="enabled" type="checkbox" :disabled="!ready||!ui.httpOnline" data-testid="strip-enabled">{{t('Включить RGB','Enable RGB')}}</label></div><div class="stream-toolbar" role="status" data-testid="strip-live-status"><span v-if="invalid||live.error.value||strip?.driver_error" class="bad">{{invalid||live.error.value||strip?.driver_error}}</span><span v-else-if="live.sending.value||live.pending.value||strip?.driver!==strip?.requested_driver">{{t('Передача…','Sending…')}}</span><span v-else class="ok">{{t('Живое управление','Live controls')}}</span><button v-if="live.error.value&&!invalid" @click="live.update(payload(),true)">{{t('Повторить','Retry')}}</button></div><output class="endpoint" data-testid="strip-state">{{t('На устройстве','Device state')}}: {{strip?.driver?.toUpperCase()}} · {{strip?.enabled?t('включено','on'):t('выключено','off')}} · {{strip?.mode??'solid'}} · {{strip?.brightness_pct??20}}% · {{strip?.period_ms??1000}} ms</output></section></template>

